function formatNumber(value) {
  return Number(value ?? 0).toLocaleString('zh-CN', { maximumFractionDigits: 0 });
}

function formatDuration(seconds) {
  const total = Math.max(0, Math.round(Number(seconds) || 0));
  return `${Math.floor(total / 60)}分${String(total % 60).padStart(2, '0')}秒`;
}

function formatTime(value) {
  const date = new Date(value);
  const options = request.periodType === 'day'
    ? {
        timeZone: 'Asia/Shanghai',
        hour: '2-digit',
        minute: '2-digit',
      }
    : {
        timeZone: 'Asia/Shanghai',
        month: '2-digit',
        day: '2-digit',
        hour: '2-digit',
        minute: '2-digit',
      };
  const parts = Object.fromEntries(new Intl.DateTimeFormat('en-CA', options)
    .formatToParts(date)
    .filter((part) => part.type !== 'literal')
    .map((part) => [part.type, part.value]));
  return request.periodType === 'day'
    ? `${parts.hour}:${parts.minute}`
    : `${parts.month}-${parts.day} ${parts.hour}:${parts.minute}`;
}

function formatDateTime(value) {
  const timestamp = Date.parse(String(value ?? ''));
  if (!Number.isFinite(timestamp)) return '未知时间';
  const parts = Object.fromEntries(new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Asia/Shanghai',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    hourCycle: 'h23',
  }).formatToParts(new Date(timestamp)).filter((part) => part.type !== 'literal').map((part) => [part.type, part.value]));
  return `${parts.year}-${parts.month}-${parts.day} ${parts.hour}:${parts.minute}`;
}

function kdRatio(summary) {
  // Deaths are a placement proxy in this workflow. A zero denominator means
  // KD is undefined, not an infinite number to show users.
  return summary.deaths > 0 ? summary.kills / summary.deaths : null;
}

function formatKdRatio(value) {
  return Number.isFinite(value) ? value.toFixed(2) : '—';
}

function sameKd(left, right) {
  return left === right || (Number.isFinite(left) && Number.isFinite(right) && Math.abs(left - right) < 0.000001);
}

function mapLabel(value) {
  return {
    Baltic_Main: '艾伦格',
    Desert_Main: '米拉玛',
    Savage_Main: '萨诺',
    DihorOtok_Main: '维寒迪',
