}

function modeLabel(value) {
  return {
    solo: '单排',
    'solo-fpp': '单排 FPP',
    duo: '双排',
    'duo-fpp': '双排 FPP',
    squad: '四排',
    'squad-fpp': '四排 FPP',
  }[value] ?? value;
}

function ordinal(index) {
  return ['1️⃣', '2️⃣', '3️⃣', '4️⃣', '5️⃣', '6️⃣', '7️⃣', '8️⃣', '9️⃣', '🔟'][index] ?? `${index + 1}.`;
}

const sortedSummaries = [...stats.values()].sort((left, right) => {
  if (left.games === 0 && right.games !== 0) return 1;
  if (right.games === 0 && left.games !== 0) return -1;
  const leftKd = kdRatio(left);
  const rightKd = kdRatio(right);
  if (leftKd !== rightKd) return rightKd > leftKd ? 1 : -1;
  if (left.kills !== right.kills) return right.kills - left.kills;
  if (left.assists !== right.assists) return right.assists - left.assists;
  return right.damage - left.damage;
});

let previousKd = null;
let previousRank = 0;
