  if (summary.games > 0) {
    previousKd = currentKd;
    previousRank = rank;
  }
  const rankIcon = rank === 1 ? '🥇' : rank === 2 ? '🥈' : rank === 3 ? '🥉' : rank ? `${rank}.` : '—';
