function findRankingResult(key) {
  const definition = funRankingDefinitions.find((item) => item.key === key);
  if (!definition) return null;
  const eligible = rankableSummaries.filter(definition.include);
  const sorted = [...eligible].sort(definition.compare);
  const winners = sorted.length > 0 ? sorted.filter((summary) => definition.same(summary, sorted[0])) : [];
  return { definition, winners };
}

