      return formatNumber(summary.top10);
    case 'survival_time':
      return formatDuration(summary.games ? summary.survived / summary.games : 0);
    default:
      return '—';
  }
}

function displayWidth(value) {
  let width = 0;
  for (const character of String(value ?? '')) {
    const codePoint = character.codePointAt(0);
    const isWide = (codePoint >= 0x1100 && codePoint <= 0x115f)
      || (codePoint >= 0x2e80 && codePoint <= 0x303e)
      || (codePoint >= 0x3040 && codePoint <= 0x33ff)
      || (codePoint >= 0xac00 && codePoint <= 0xd7a3)
      || (codePoint >= 0xf900 && codePoint <= 0xfaff)
      || (codePoint >= 0xfe10 && codePoint <= 0xfe6f)
      || (codePoint >= 0xff01 && codePoint <= 0xff60)
      || (codePoint >= 0x1f300 && codePoint <= 0x1faff);
    width += isWide ? 2 : 1;
  }
  return width;
}

function padTableCell(value, width, alignment = 'left') {
  const text = String(value ?? '—').replace(/[\r\n]+/g, ' ');
  const gap = Math.max(width - displayWidth(text), 0);
  if (alignment === 'right') return `${' '.repeat(gap)}${text}`;
  if (alignment === 'center') {
    const leftGap = Math.floor(gap / 2);
    return `${' '.repeat(leftGap)}${text}${' '.repeat(gap - leftGap)}`;
  }
  return `${text}${' '.repeat(gap)}`;
}

function formatMetricTable(summaries, metrics) {
  const headers = ['队员', ...metrics.map((metric) => metricLabels[metric] ?? metric)];
  const rows = summaries.map((summary) => [
    summary.playerName,
    ...metrics.map((metric) => formatMetricCell(summary, metric)),
  ]);
  const widths = headers.map((header, index) => Math.max(
    displayWidth(header),
    ...rows.map((row) => displayWidth(row[index])),
  ));
  const horizontal = (left, joint, right) => `${left}${widths.map((width) => '─'.repeat(width + 2)).join(joint)}${right}`;
  const formatRow = (cells, isHeader = false) => `│ ${cells.map((cell, index) => padTableCell(cell, widths[index], index === 0 ? 'left' : isHeader ? 'center' : 'right')).join(' │ ')} │`;
  return [
    '```',
    horizontal('┌', '┬', '┐'),
    formatRow(headers, true),
    horizontal('├', '┼', '┤'),
    ...rows.map((row) => formatRow(row)),
    horizontal('└', '┴', '┘'),
    '```',
  ].join('\n');
}

function formatMetricValue(summary, metric) {
  switch (metric) {
    case 'kd':
      return `⚔️ KD ${summary.kills}/${summary.deaths}（${formatKdRatio(kdRatio(summary))}）`;
    case 'kills':
      return `🔫 击杀 ${formatNumber(summary.kills)}`;
    case 'assists':
      return `🤝 助攻 ${formatNumber(summary.assists)}`;
    case 'damage':
      return `💥 伤害 ${formatNumber(summary.damage)}`;
    case 'dbnos':
      return `💀 倒地 ${formatNumber(summary.dbnos)}`;
    case 'revives':
      return `🚑 救援 ${formatNumber(summary.revives)}`;
    case 'rank':
      return `📍 平均排名 #${formatAverage(averagePlacement(summary))}`;
    case 'wins':
      return `🏆 吃鸡 ${formatNumber(summary.wins)}`;
    case 'top10':
      return `🔟 前十 ${formatNumber(summary.top10)}`;
    case 'survival_time':
      return `⏱️ 平均存活 ${formatDuration(summary.games ? summary.survived / summary.games : 0)}`;
    default:
      return null;
  }
}

function formatPlayerMetricLine(summary, metrics = breakdownMetrics) {
  const values = [`${summary.icon} ${summary.playerName}`, `🎮 ${summary.games} 局`];
  for (const metric of metrics) {
