    if (value) values.push(value);
  }
  return values.join('｜');
}

const contextFocusPlayerNames = Array.isArray(request.contextFocusPlayerNames)
  ? new Set(request.contextFocusPlayerNames.map(String))
  : new Set();
const focusSummaries = [...stats.values()].filter((summary) => contextFocusPlayerNames.has(summary.playerName));
const breakdownSummaries = request.contextApplied && contextFocusPlayerNames.size > 0 && !asksRanking
