  : null;
const compareMetrics = breakdownMetrics.length > 0 ? breakdownMetrics : ['kd', 'assists'];
const compareSummaries = request.contextApplied && contextFocusPlayerNames.size > 0 && !asksRanking
  ? focusSummaries
  : [...stats.values()];
const compareOutput = compareSummaries.length > 1
