function parseJson(value) {
  if (value && typeof value === 'object') return value;
  if (typeof value === 'string') {
    try {
      return JSON.parse(value);
    } catch {
      return null;
    }
  }
  return null;
}

function parseTime(value) {
  const time = Date.parse(String(value ?? ''));
  return Number.isFinite(time) ? time : 0;
}

function parseDateLabel(label) {
  const match = String(label ?? '').match(/^(\d{4})-(\d{2})-(\d{2})$/);
  return match ? { year: Number(match[1]), month: Number(match[2]), day: Number(match[3]) } : null;
}

function periodStartMs(label) {
  return Date.parse(`${label}T06:00:00+08:00`);
}

function addDays(label, amount) {
  const parts = parseDateLabel(label);
  if (!parts) return null;
  const date = new Date(Date.UTC(parts.year, parts.month - 1, parts.day + amount));
  return `${date.getUTCFullYear()}-${String(date.getUTCMonth() + 1).padStart(2, '0')}-${String(date.getUTCDate()).padStart(2, '0')}`;
}

function formatPeriodRange(startLabel, endLabel) {
  return `${startLabel} 06:00 至 ${endLabel} 06:00（北京时间）`;
}

function isValidPeriod(startLabel, endLabel) {
  return Boolean(
    parseDateLabel(startLabel)
      && parseDateLabel(endLabel)
      && Number.isFinite(periodStartMs(startLabel))
      && Number.isFinite(periodStartMs(endLabel)),
  );
}

const request = $('Normalize Request').first()?.json ?? {};
const rows = $input.all().map((item) => item.json ?? {});
const nowMs = Date.now();
const retentionMs = Number(request.matchCacheTtlMs ?? 14 * 24 * 60 * 60 * 1000);
const playerCacheKey = request.playerCacheKey ?? '';
const cacheByKey = new Map();
const cachedMatchRecords = [];
let cacheAsOfMs = 0;

for (const row of rows) {
  const cacheKey = String(row.cacheKey ?? '');
  const payload = parseJson(row.payload);
  if (!cacheKey || !payload) continue;

  const refreshedAtMs = parseTime(row.refreshedAt);
  cacheByKey.set(cacheKey, { ...row, payload });

  const isMatchRow = row.cacheType === 'match' || cacheKey.startsWith('match:');
  if (!isMatchRow) continue;
  cacheAsOfMs = Math.max(cacheAsOfMs, refreshedAtMs);
  if (!payload.matchId) continue;
  const matchTimestamp = Number(payload.timestamp ?? parseTime(payload.createdAt));
  if (Number.isFinite(matchTimestamp) && matchTimestamp >= nowMs - retentionMs) {
    cachedMatchRecords.push(payload);
  }
}

const contextKey = String(request.contextKey ?? '').trim();
const contextEntry = contextKey ? cacheByKey.get(contextKey) : null;
const contextPayload = contextEntry?.payload;
const contextExpiresAt = Number(contextEntry?.expiresAt ?? contextPayload?.expiresAt ?? 0);
const contextFresh = Boolean(
  contextPayload
    && contextExpiresAt > nowMs
    && isValidPeriod(contextPayload.rangeStartLabel, contextPayload.rangeEndLabel),
);
const useContext = Boolean(request.contextualFollowup && !request.periodExplicit && contextFresh);
let effectiveRequest = { ...request, contextApplied: false };

if (useContext) {
  const contextStartLabel = contextPayload.rangeStartLabel;
  const contextEndLabel = contextPayload.rangeEndLabel;
  const contextStartMs = periodStartMs(contextStartLabel);
  const contextEndBoundaryMs = periodStartMs(contextEndLabel);
  const contextEndMs = Math.min(contextEndBoundaryMs, nowMs);
  const contextPlan = contextPayload.queryPlan && typeof contextPayload.queryPlan === 'object'
    ? contextPayload.queryPlan
    : {};
  const currentPlan = request.queryPlan && typeof request.queryPlan === 'object'
    ? request.queryPlan
    : {};
  const currentMetrics = Array.isArray(currentPlan.metrics) ? currentPlan.metrics : [];
  const currentIsGeneric = currentPlan.operation === 'report' && currentMetrics.length === 0;
  let effectivePlan = { ...currentPlan };

  if (currentIsGeneric && Object.keys(contextPlan).length > 0) {
    effectivePlan = { ...contextPlan, contextInherited: true };
  }
  if (request.allPlayersRequested && currentMetrics.length === 0) {
    effectivePlan = {
      ...effectivePlan,
      operation: 'per_player',
      metrics: Array.isArray(contextPlan.metrics) && contextPlan.metrics.length > 0 ? contextPlan.metrics : ['kda'],
      group_by: 'player',
      contextInherited: true,
    };
  } else if (currentPlan.operation === 'report' && currentMetrics.length > 0 && contextPlan.operation === 'per_player') {
    effectivePlan = {
      ...effectivePlan,
      operation: 'per_player',
      group_by: 'player',
      contextInherited: true,
    };
  } else if (currentPlan.operation === 'report' && currentMetrics.length > 0 && !currentPlan.ranking) {
    effectivePlan = {
      ...effectivePlan,
      operation: 'per_player',
      group_by: 'player',
      contextInherited: true,
    };
  }

  const contextFocusPlayerNames = request.allPlayersRequested
    ? [...(request.playerNames ?? [])]
    : Array.isArray(contextPayload.focusPlayerNames)
      ? [...new Set(contextPayload.focusPlayerNames.map(String))]
      : [];
  effectiveRequest = {
    ...request,
    queryPlan: effectivePlan,
    dateLabel: contextStartLabel,
    periodLabel: contextPayload.periodLabel ?? request.periodLabel,
    periodType: contextPayload.periodType ?? request.periodType,
    reportTitle: contextPayload.reportTitle ?? request.reportTitle,
    selectionSource: 'context',
    rangeStartLabel: contextStartLabel,
    rangeEndLabel: contextEndLabel,
    rangeStartMs: contextStartMs,
    rangeEndBoundaryMs: contextEndBoundaryMs,
    startMs: contextStartMs,
    endMs: contextEndMs,
    isPartial: contextStartMs <= nowMs && nowMs < contextEndBoundaryMs && contextEndMs < contextEndBoundaryMs,
    rangeText: formatPeriodRange(contextStartLabel, contextEndLabel),
    contextApplied: true,
    contextFresh: true,
    contextPayload,
    contextFocusPlayerNames,
  };
}

const playerEntry = cacheByKey.get(effectiveRequest.playerCacheKey ?? playerCacheKey);
const playerPayload = playerEntry?.payload;
const hasPlayerPayload = Array.isArray(playerPayload?.players) && playerPayload.players.length > 0;
const playerEntryExpiresAt = Number(playerEntry?.expiresAt ?? 0);
const playerCacheValid = hasPlayerPayload && playerEntryExpiresAt > nowMs;
const cacheStatus = playerCacheValid ? 'fresh' : hasPlayerPayload ? 'stale' : 'empty';
const playerCacheRefreshedAt = playerEntry?.refreshedAt ?? null;

return [{
  json: {
    ...effectiveRequest,
    originalRequest: {
      queryPlan: request.queryPlan ?? {},
      periodLabel: request.periodLabel,
      rangeStartLabel: request.rangeStartLabel,
      rangeEndLabel: request.rangeEndLabel,
    },
    playerCacheKey: effectiveRequest.playerCacheKey ?? playerCacheKey,
    playerCacheValid,
    needsPlayerLookup: !playerCacheValid,
    cacheStatus,
    freshPlayerPayload: playerCacheValid ? playerPayload : null,
    stalePlayerPayload: hasPlayerPayload ? playerPayload : null,
    playerCacheRefreshedAt,
    cachedMatchRecords,
    cachedMatchCount: cachedMatchRecords.length,
    cacheAsOfAt: cacheAsOfMs ? new Date(cacheAsOfMs).toISOString() : null,
    cacheReadAt: new Date(nowMs).toISOString(),
    contextFresh,
    contextPayload: contextFresh ? contextPayload : null,
  },
}];

function makePlayerMap(snapshots) {
  return Object.fromEntries(snapshots.map((player) => [player.accountId, {
    accountId: player.accountId,
    playerName: player.playerName,
    displayName: player.displayName,
  }]));
}

const request = $('Prepare Cache').first()?.json ?? $('Normalize Request').first()?.json ?? {};
const state = $('Prepare Cache').first()?.json ?? {};
const payload = state.freshPlayerPayload ?? state.stalePlayerPayload;
const payloadPlayers = Array.isArray(payload?.players) ? payload.players : [];
const payloadById = new Map(payloadPlayers.map((player) => [String(player.accountId), player]));
const snapshots = (request.players ?? []).map((requested) => {
  const cached = payloadById.get(String(requested.accountId));
  return {
    accountId: requested.accountId,
    playerName: requested.playerName,
    displayName: requested.displayName,
    found: cached?.found !== false,
    matchIds: Array.isArray(cached?.matchIds) ? [...new Set(cached.matchIds.map(String))] : [],
  };
});

return [{
  json: {
    ...request,
    playerMap: makePlayerMap(snapshots),
    playerSnapshots: snapshots,
    foundPlayers: snapshots.filter((player) => player.found),
    missingPlayers: snapshots.filter((player) => !player.found),
    matchIds: [...new Set(snapshots.flatMap((player) => player.matchIds))],
    playerLookupFetchedAt: payload?.fetchedAt ?? state.cacheAsOfAt ?? null,
    shouldWritePlayerCache: false,
    usedStaleCache: false,
    lookupError: payload ? '' : '查询 PUBG 玩家失败：缓存为空，且未能完成同步。',
    rateLimit: payload?.rateLimit ?? null,
    cacheAsOfAt: payload?.fetchedAt ?? state.cacheAsOfAt ?? null,
  },
}];

const request = $('Prepare Cache').first()?.json ?? $('Normalize Request').first()?.json ?? {};
const source = $input.first()?.json ?? {};
const cacheState = $('Prepare Cache').first()?.json ?? {};
const snapshots = Array.isArray(source.playerSnapshots) ? source.playerSnapshots : [];
const cachedRecords = Array.isArray(cacheState.cachedMatchRecords) ? cacheState.cachedMatchRecords : [];
const cachedMatchIds = new Set(cachedRecords.map((record) => String(record.matchId)).filter(Boolean));
const matchIds = [...new Set(snapshots.flatMap((player) => Array.isArray(player.matchIds) ? player.matchIds.map(String) : []))];
const missingMatchIds = source.lookupError && !source.usedStaleCache
  ? []
  : matchIds.filter((matchId) => !cachedMatchIds.has(matchId));
const common = {
  ...request,
  playerMap: source.playerMap ?? {},
  playerSnapshots: snapshots,
  foundPlayers: source.foundPlayers ?? [],
  missingPlayers: source.missingPlayers ?? request.players ?? [],
  matchIds,
  lookupError: source.lookupError ?? '',
  usedStaleCache: Boolean(source.usedStaleCache),
  playerLookupFetchedAt: source.playerLookupFetchedAt ?? null,
  cacheAsOfAt: source.cacheAsOfAt ?? cacheState.cacheAsOfAt ?? null,
  cacheStatus: cacheState.cacheStatus ?? 'empty',
  playerCacheValid: Boolean(cacheState.playerCacheValid),
  playerLookupFromCache: !source.shouldWritePlayerCache,
  cachedMatchCount: cachedRecords.length,
  cachedMatchIds: [...cachedMatchIds],
  newMatchCount: missingMatchIds.length,
  hasMissingMatches: missingMatchIds.length > 0,
  rateLimit: source.rateLimit ?? null,
};

if (missingMatchIds.length === 0) {
  return [{
    json: {
      ...common,
      matchId: null,
      shard: request.shard,
    },
  }];
}

return missingMatchIds.map((matchId) => ({
  json: {
    ...common,
    matchId,
    shard: request.shard,
  },
}));

const source = $input.first()?.json ?? {};
if (!source.shouldWritePlayerCache || !source.playerCachePayload || !source.playerCacheKey) return [];

return [{
  json: {
    cacheKey: source.playerCacheKey,
    cacheType: 'playerLookup',
    payload: JSON.stringify(source.playerCachePayload),
    refreshedAt: source.playerLookupFetchedAt ?? new Date().toISOString(),
    expiresAt: Date.now() + Number(source.playerCacheTtlMs ?? 60 * 1000),
  },
}];

return $input.all().map((item) => item.json ?? {}).filter((source) => source.cacheable && source.matchId).map((source) => {
  const payload = {
    schemaVersion: 1,
    matchId: source.matchId,
    shard: source.shard ?? 'steam',
    createdAt: source.createdAt ?? null,
    timestamp: Number(source.timestamp ?? 0),
    matchType: source.matchType ?? '',
    gameMode: source.gameMode ?? '',
    isCompetitive: Boolean(source.isCompetitive),
    mapName: source.mapName ?? '未知地图',
    duration: Number(source.duration ?? 0),
    patchVersion: source.patchVersion ?? '',
    players: Array.isArray(source.players) ? source.players : [],
  };

  return {
    json: {
      cacheKey: `match:${payload.shard}:${payload.matchId}`,
      cacheType: 'match',
      payload: JSON.stringify(payload),
      refreshedAt: new Date().toISOString(),
      expiresAt: Date.now() + Number(source.matchCacheTtlMs ?? 14 * 24 * 60 * 60 * 1000),
    },
  };
});

const request = $('Prepare Cache').first()?.json ?? $('Normalize Request').first()?.json ?? {};
const result = $input.first()?.json ?? {};
const contextKey = String(request.contextKey ?? '').trim();
if (!contextKey || !result.contextPayload) return [];

const updatedAt = new Date().toISOString();
const expiresAt = Date.now() + Number(request.contextTtlMs ?? 12 * 60 * 60 * 1000);
const payload = {
  ...result.contextPayload,
  updatedAt,
  expiresAt,
  contextKey,
};

return [{
  json: {
    cacheKey: contextKey,
    cacheType: 'context',
    payload: JSON.stringify(payload),
    refreshedAt: updatedAt,
    expiresAt,
  },
}];
